---@class CompetePollBaseBehaviours
local CompetePollBaseBehaviours = Class('CompetePollBaseBehaviours')

function CompetePollBaseBehaviours:__init()
    
    self.refreshEvent = Events.AddListener(Constants.EventNames.CompeteTotalPointRefresh ,Bind(self, self.RefreshUI))
end

function CompetePollBaseBehaviours:__delete()
    
    Events.RemoveListener( Constants.EventNames.CompeteTotalPointRefresh ,self.refreshEvent)
end

function CompetePollBaseBehaviours:Awake()
    self:RefreshUI()
end

function CompetePollBaseBehaviours:RefreshUI()
    if isNull(self.index) then
        return
    end
    local TextComp = {path = "Root/Container/FlowerTotal/TextNumber" , comp = typeof(CS.UnityEngine.UI.Text)}
    ---@type CompeteComponent
    local CompeteComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CompeteComponent)
    local RawImageAlterable = {path = "Root/Container/FlowerTotal/ImgFlower" ,comp = typeof(CS.Engine.UI.RawImageAlterable)}
    local propId = CompeteComponent:GetPropId()
    local sprite = GoodsConfMgr:GetPhotoPathById(propId)
    
    ---@type UnityEngine.UI.Text
    local text =  CompeteComponent:GetComponent(self.controller ,TextComp)
    local ImgFlower =  CompeteComponent:GetComponent(self.controller ,RawImageAlterable)
    ImgFlower:LoadSprite(sprite)
    local activityConf =  CompeteComponent:GetActivityConf()
    local people = activityConf.people or {}
    local userPkPointInfo = CompeteComponent:GetUserPkPointInfo()
    self.index = self.index or 0
    if not isNull(text) then
        local roleId = tostring(people[self.index])
        text.text = tostring(checkInt(userPkPointInfo[roleId]))
    end
end

function CompetePollBaseBehaviours:Start()

end

function CompetePollBaseBehaviours:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end
return CompetePollBaseBehaviours